func _key(code: Key) -> InputEventKey:
	var ev := InputEventKey.new()
	ev.physical_keycode = code
	return ev

func _action(keys: Array) -> Dictionary:
	var events: Array = []
	for k in keys:
		events.append(_key(k))
	return {"deadzone": 0.2, "events": events}

