extends RefCounted
## Sparse voxel volume that can be sculpted with a few primitive fills and then
## baked into a single vertex-coloured ArrayMesh.
##
## Coordinates are continuous "voxel units": voxel (i, j, k) occupies the cube
## [i, i+1] x [j, j+1] x [k, k+1]. The fill helpers include a voxel when its
## centre lies inside the primitive.
##
## The mesher only emits faces that are exposed to air and bakes a cheap
## per-vertex ambient occlusion term plus a tiny per-voxel brightness jitter
## into the vertex colours, which is what gives the blocks their depth.

## Tangent axes for a face whose normal is along axis a: (u, v) = (a+1, a+2),
## so that u x v = +a.
const _AXIS_U := [1, 2, 0]
const _AXIS_V := [2, 0, 1]
## Brightness for ambient-occlusion levels 0 (fully boxed in) .. 3 (open).
const _AO_CURVE := [0.0, 0.55, 0.8, 1.0]

var voxels: Dictionary = {}  # Vector3i -> Color


func set_voxel(p: Vector3i, c: Color) -> void:
	voxels[p] = c


func erase_voxel(p: Vector3i) -> void:
	voxels.erase(p)


func has_voxel(p: Vector3i) -> bool:
	return voxels.has(p)


func count() -> int:
	return voxels.size()


## Copies every voxel of `other` into this model, shifted by `offset` voxels.
func merge(other: RefCounted, offset: Vector3i = Vector3i.ZERO) -> void:
	for p: Vector3i in other.voxels:
		voxels[p + offset] = other.voxels[p]


## Axis-aligned box from `lo` to `hi` (continuous voxel units).
func fill_box(lo: Vector3, hi: Vector3, c: Color) -> void:
	var x0 := int(floor(lo.x))
	var y0 := int(floor(lo.y))
	var z0 := int(floor(lo.z))
	for x in range(x0, int(ceil(hi.x)) + 1):
		var cx := x + 0.5
		if cx < lo.x or cx > hi.x:
			continue
		for y in range(y0, int(ceil(hi.y)) + 1):
			var cy := y + 0.5
			if cy < lo.y or cy > hi.y:
				continue
			for z in range(z0, int(ceil(hi.z)) + 1):
				var cz := z + 0.5
				if cz < lo.z or cz > hi.z:
					continue
				voxels[Vector3i(x, y, z)] = c


func fill_ellipsoid(center: Vector3, radii: Vector3, c: Color) -> void:
	var lo := (center - radii).floor()
	var hi := (center + radii).ceil()
	for x in range(int(lo.x), int(hi.x) + 1):
		for y in range(int(lo.y), int(hi.y) + 1):
			for z in range(int(lo.z), int(hi.z) + 1):
				var d := (Vector3(x + 0.5, y + 0.5, z + 0.5) - center) / radii
				if d.length_squared() <= 1.0:
					voxels[Vector3i(x, y, z)] = c


## Tapered elliptical "bone" running from `a` to `b`. The axis has to lie in a
## constant-z plane (the horse's sagittal plane). `r_a` / `r_b` are
## (in-plane radius, lateral radius) at each end. With `flat_ends` the tube is
## cut square at both ends, otherwise the ends are rounded.
func fill_taper(a: Vector3, b: Vector3, r_a: Vector2, r_b: Vector2, c: Color,
		flat_ends: bool = false) -> void:
	var axis := Vector2(b.x - a.x, b.y - a.y)
	var len_sq := maxf(axis.length_squared(), 0.0001)
	var rmax := maxf(maxf(r_a.x, r_b.x), maxf(r_a.y, r_b.y))
	var lo := Vector3(minf(a.x, b.x), minf(a.y, b.y), a.z - rmax).floor() - Vector3(rmax, rmax, 0.0).ceil()
	var hi := Vector3(maxf(a.x, b.x), maxf(a.y, b.y), a.z + rmax).ceil() + Vector3(rmax, rmax, 0.0).ceil()
	for x in range(int(lo.x), int(hi.x) + 1):
		for y in range(int(lo.y), int(hi.y) + 1):
			var rel := Vector2(x + 0.5 - a.x, y + 0.5 - a.y)
			var t := rel.dot(axis) / len_sq
			if flat_ends and (t < 0.0 or t > 1.0):
				continue
			t = clampf(t, 0.0, 1.0)
			var inplane := (rel - axis * t).length()
			var rad := r_a.lerp(r_b, t)
			for z in range(int(lo.z), int(hi.z) + 1):
				var dz := z + 0.5 - a.z
				var q := (inplane / rad.x) * (inplane / rad.x) + (dz / rad.y) * (dz / rad.y)
				if q <= 1.0:
					voxels[Vector3i(x, y, z)] = c


## Rewrites every voxel colour with `fn(p: Vector3i, c: Color) -> Color`.
func recolor(fn: Callable) -> void:
	for p: Vector3i in voxels.keys():
		voxels[p] = fn.call(p, voxels[p])


func get_bounds() -> AABB:
	var lo := Vector3i(1 << 30, 1 << 30, 1 << 30)
	var hi := Vector3i(-(1 << 30), -(1 << 30), -(1 << 30))
	for p: Vector3i in voxels:
		lo = lo.min(p)
		hi = hi.max(p)
	return AABB(Vector3(lo), Vector3(hi - lo + Vector3i.ONE))


static func hash01(p: Vector3i) -> float:
	var h: int = (p.x * 374761393 + p.y * 668265263 + p.z * 2147483629) & 0x7fffffff
	h = ((h ^ (h >> 13)) * 1274126177) & 0x7fffffff
	return float(h % 1021) / 1020.0


func _solid(p: Vector3i) -> int:
	return 1 if voxels.has(p) else 0


## Bakes the volume into a mesh. `pivot` (in voxel units) becomes the origin of
## the mesh, `ao_strength` scales the darkening in creases and `jitter` is the
## +/- brightness variation between neighbouring voxels.
func build_mesh(voxel_size: float, pivot: Vector3 = Vector3.ZERO, ao_strength: float = 0.5,
		jitter: float = 0.05) -> ArrayMesh:
	var verts := PackedVector3Array()
	var normals := PackedVector3Array()
	var colors := PackedColorArray()
	var indices := PackedInt32Array()
	var ao := [0, 0, 0, 0]
	var vi := 0

	for p: Vector3i in voxels:
		var base: Color = voxels[p]
		var tint := 1.0 + (hash01(p) - 0.5) * 2.0 * jitter
		for face in 6:
			var axis := face >> 1
			var positive := (face & 1) == 0
			var n := Vector3i.ZERO
			n[axis] = 1 if positive else -1
			if voxels.has(p + n):
				continue
			var u_axis: int = _AXIS_U[axis]
			var v_axis: int = _AXIS_V[axis]
			var du := Vector3i.ZERO
			var dv := Vector3i.ZERO
			du[u_axis] = 1
			dv[v_axis] = 1
			# Corner order is clockwise seen from outside (Godot's front face).
			var corners := [[0, 0], [0, 1], [1, 1], [1, 0]] if positive \
					else [[0, 0], [1, 0], [1, 1], [0, 1]]
			var outside := p + n
			var origin := Vector3(p)
			if positive:
				origin[axis] += 1.0
			for i in 4:
				var cu: int = corners[i][0]
				var cv: int = corners[i][1]
				var su := du * (cu * 2 - 1)
				var sv := dv * (cv * 2 - 1)
				var s1 := _solid(outside + su)
				var s2 := _solid(outside + sv)
				var s3 := _solid(outside + su + sv)
				ao[i] = 0 if (s1 == 1 and s2 == 1) else 3 - (s1 + s2 + s3)
				var shade := 1.0 - ao_strength * (1.0 - _AO_CURVE[ao[i]])
				shade *= tint
				verts.append((origin + Vector3(du) * cu + Vector3(dv) * cv - pivot) * voxel_size)
				normals.append(Vector3(n))
				colors.append(Color(base.r * shade, base.g * shade, base.b * shade, base.a))
			if ao[0] + ao[2] >= ao[1] + ao[3]:
				indices.append_array([vi, vi + 1, vi + 2, vi, vi + 2, vi + 3])
			else:
				indices.append_array([vi + 1, vi + 2, vi + 3, vi + 1, vi + 3, vi])
			vi += 4

	var arrays := []
	arrays.resize(Mesh.ARRAY_MAX)
	arrays[Mesh.ARRAY_VERTEX] = verts
	arrays[Mesh.ARRAY_NORMAL] = normals
	arrays[Mesh.ARRAY_COLOR] = colors
	arrays[Mesh.ARRAY_INDEX] = indices
	var mesh := ArrayMesh.new()
	if vi > 0:
		mesh.add_surface_from_arrays(Mesh.PRIMITIVE_TRIANGLES, arrays)
	return mesh

extends RefCounted
## Voxel sculpt of the horse, split into rigid parts for animation.
##
## Model space: +X is forward, +Y up, +Z the horse's right; one voxel is
## VOXEL metres and the hooves stand on y = 0. Every builder returns a
## VoxelModel positioned in that shared space; the rig constants below say
## where each part pivots. The animation code turns those into a node tree.

const VoxelModel := preload("res://scripts/voxel_model.gd")

const VOXEL := 0.06

# ---- Rig layout (voxel units, model space) --------------------------------
const BODY_PIVOT := Vector3(14.0, 18.0, 0.0)
const NECK_PIVOT := Vector3(22.5, 20.5, 0.0)
const HEAD_PIVOT := Vector3(29.5, 29.0, 0.0)
const TAIL_PIVOT := Vector3(1.6, 22.0, 0.0)
## Shoulder / hip joint of the right-hand legs (left legs mirror z).
const FORE_PIVOT := Vector3(22.5, 17.5, 3.0)
const HIND_PIVOT := Vector3(4.5, 17.5, 3.5)

## Bone lengths: pivot -> knee (hock) -> fetlock; the hoof piece hangs below.
const FORE_UPPER := 10.0
const FORE_LOWER := 4.5
const HIND_UPPER := 8.5
const HIND_LOWER := 6.0
const HOOF_LEN := 3.0

const TAIL_SEGMENTS := 3
const TAIL_SEG_LEN := 6.0
const MANE_TUFTS := 6

# ---- Palette (sRGB) ---------------------------------------------------------
const COAT := Color("#a4552a")
const COAT_DARK := Color("#7f3f1e")
const COAT_LIGHT := Color("#c8814a")
const MANE := Color("#2a1911")
const HOOF := Color("#2b2624")
const SOCK := Color("#efe7da")
const MUZZLE := Color("#b9806c")
const EYE := Color("#0c0908")
const NOSTRIL := Color("#3a231c")

const HEAD_ANGLE_DEG := -55.0
const HEAD_LENGTH := 11.0
const NECK_LENGTH_VEC := Vector2(7.0, 8.5)  # from NECK_PIVOT to HEAD_PIVOT


static func _coat_for_height(y: float) -> Color:
	var t := clampf((y - 12.0) / 12.5, 0.0, 1.0)
	return COAT_LIGHT.lerp(COAT_DARK, smoothstep(0.05, 0.95, t))


static func build_torso() -> VoxelModel:
	var m := VoxelModel.new()
	m.fill_ellipsoid(Vector3(6.5, 18.3, 0.0), Vector3(7.0, 5.7, 5.2), COAT)    # rump
	m.fill_ellipsoid(Vector3(14.5, 18.2, 0.0), Vector3(8.8, 5.8, 5.1), COAT)   # barrel
	m.fill_ellipsoid(Vector3(21.8, 18.6, 0.0), Vector3(6.0, 6.0, 4.4), COAT)   # chest
	m.fill_ellipsoid(Vector3(19.0, 23.6, 0.0), Vector3(3.5, 1.7, 1.9), COAT)   # withers
	m.recolor(func(p: Vector3i, _c: Color) -> Color: return _coat_for_height(p.y + 0.5))
	return m


static func build_neck() -> VoxelModel:
	var m := VoxelModel.new()
	var a := NECK_PIVOT
	var b := HEAD_PIVOT + Vector3(-0.5, -0.5, 0.0)
	m.fill_taper(a + Vector3(-1.5, -1.0, 0.0), b, Vector2(4.6, 3.1), Vector2(2.7, 2.1), COAT)
	var axis := Vector2(b.x - a.x, b.y - a.y).normalized()
	m.recolor(func(p: Vector3i, _c: Color) -> Color:
		# Darker along the crest (up/back side of the neck), lighter underneath.
		var rel := Vector2(p.x + 0.5 - a.x, p.y + 0.5 - a.y)
		var side := rel.x * -axis.y + rel.y * axis.x  # +: away from the throat
		var t := clampf(0.5 + side / 7.0, 0.0, 1.0)
		return COAT_LIGHT.lerp(COAT_DARK, smoothstep(0.1, 0.95, t)))
	return m


static func head_axis() -> Vector3:
	var ang := deg_to_rad(HEAD_ANGLE_DEG)
	return Vector3(cos(ang), sin(ang), 0.0)


static func build_head() -> VoxelModel:
	var m := VoxelModel.new()
	var p0 := HEAD_PIVOT
	var dir := head_axis()
	var perp := Vector3(-dir.y, dir.x, 0.0)  # towards the bridge of the nose
	# Skull and jaw, long face, then the muzzle.
	m.fill_taper(p0 - dir * 1.0, p0 + dir * 5.0, Vector2(3.4, 2.4), Vector2(2.9, 2.2), COAT)
	m.fill_taper(p0 + dir * 4.0, p0 + dir * 10.0, Vector2(2.7, 2.2), Vector2(1.7, 1.25), COAT)
	m.fill_taper(p0 + dir * 9.0, p0 + dir * 11.0, Vector2(1.9, 1.25), Vector2(1.6, 1.2), COAT)
	# Ears.
	for sz in [-1.5, 1.5]:
		m.fill_taper(Vector3(p0.x + 0.2, p0.y + 1.4, sz), Vector3(p0.x - 0.8, p0.y + 5.0, sz),
				Vector2(1.0, 0.6), Vector2(0.55, 0.5), COAT)
	# Forelock falling between the ears onto the forehead.
	m.fill_taper(Vector3(p0.x + 1.6, p0.y + 1.8, 0.0), Vector3(p0.x + 2.9, p0.y - 2.6, 0.0),
			Vector2(1.0, 1.0), Vector2(0.9, 1.0), MANE)

	# Paint blaze, muzzle, eyes, nostrils.
	var length := HEAD_LENGTH
	m.recolor(func(p: Vector3i, c: Color) -> Color:
		var rel := Vector3(p.x + 0.5, p.y + 0.5, 0.0) - Vector3(p0.x, p0.y, 0.0)
		var t := rel.dot(dir) / length
		var s := rel.dot(perp)
		if c == MANE:
			return MANE
		if p.y + 0.5 > p0.y + 1.0:  # ears
			return COAT_DARK.lerp(MANE, clampf((p.y + 0.5 - p0.y - 3.0) / 2.5, 0.0, 1.0))
		var col := _coat_for_height(p.y + 0.5 + 2.0)
		if t > 0.83:
			col = MUZZLE
		if s > 1.1 and absf(p.z + 0.5) < 1.0 and t > 0.12 and t < 0.86:
			col = SOCK  # white blaze down the nose
		return col)
	var eye_c := p0 + dir * 3.3 + perp * 0.7
	for zi in [-2, 1]:
		var ep := Vector3i(int(floor(eye_c.x)), int(floor(eye_c.y)), zi)
		m.set_voxel(ep, EYE)
	var nose_c := p0 + dir * 10.2 + perp * 0.3
	for zi in [-1, 0]:
		m.set_voxel(Vector3i(int(floor(nose_c.x)), int(floor(nose_c.y)), zi), NOSTRIL)
	return m


## A tuft of mane growing along +Y from its pivot at the origin.
static func build_mane_tuft(length: float, radius: float) -> VoxelModel:
	var m := VoxelModel.new()
	m.fill_taper(Vector3(0.0, -0.5, 0.0), Vector3(0.0, length, 0.0), Vector2(radius, 1.25),
			Vector2(radius * 0.55, 0.9), MANE)
	return m


## Tail segment hanging along -Y from its pivot at the origin.
static func build_tail_segment(index: int) -> VoxelModel:
	var m := VoxelModel.new()
	var f := float(index) / float(TAIL_SEGMENTS - 1)
	var top_r := Vector2(lerpf(1.9, 2.3, f), lerpf(1.9, 1.6, f))
	var bot_r := Vector2(lerpf(2.1, 0.9, f), lerpf(1.7, 0.9, f))
	m.fill_taper(Vector3(0.0, 0.8, 0.0), Vector3(0.0, -TAIL_SEG_LEN, 0.0), top_r, bot_r, MANE)
	return m


static func build_upper_leg(front: bool) -> VoxelModel:
	var m := VoxelModel.new()
	var len_up := FORE_UPPER if front else HIND_UPPER
	if front:
		m.fill_taper(Vector3(0.0, 3.0, 0.0), Vector3(0.0, -len_up, 0.0), Vector2(3.0, 2.3),
				Vector2(1.7, 1.6), COAT)
	else:
		m.fill_taper(Vector3(0.0, 3.5, 0.0), Vector3(0.0, -len_up, 0.0), Vector2(3.9, 2.9),
				Vector2(1.8, 1.6), COAT)
	m.recolor(func(p: Vector3i, _c: Color) -> Color:
		return _coat_for_height(14.0 + (p.y + 0.5) * 0.4))
	return m


static func build_lower_leg(front: bool) -> VoxelModel:
	var m := VoxelModel.new()
	var len_low := FORE_LOWER if front else HIND_LOWER
	# Knee / hock cap, then the slender cannon with a fetlock ball at its foot.
	m.fill_taper(Vector3(0.0, 1.2, 0.0), Vector3(0.0, -len_low * 0.5, 0.0), Vector2(1.9, 1.6),
			Vector2(1.25, 1.2), COAT)
	m.fill_taper(Vector3(0.0, -len_low * 0.3, 0.0), Vector3(0.0, -len_low - 0.5, 0.0),
			Vector2(1.25, 1.2), Vector2(1.7, 1.6), COAT)
	m.recolor(func(p: Vector3i, _c: Color) -> Color:
		var y := p.y + 0.5
		if y < -len_low * 0.55:
			return SOCK
		return _coat_for_height(13.0 + y * 0.5))
	return m


static func build_hoof() -> VoxelModel:
	var m := VoxelModel.new()
	# Pastern angled slightly forward, then the hoof capsule flat on the ground.
	m.fill_taper(Vector3(0.0, 0.6, 0.0), Vector3(0.6, -1.6, 0.0), Vector2(1.5, 1.4),
			Vector2(1.5, 1.5), SOCK)
	m.fill_box(Vector3(-1.4, -HOOF_LEN, -1.9), Vector3(2.4, -1.4, 1.9), HOOF)
	m.fill_box(Vector3(-0.6, -1.4, -1.5), Vector3(1.6, -0.9, 1.5), SOCK)
	return m


static func make_material() -> StandardMaterial3D:
	return VoxelModel.make_material()

extends Node3D
## A voxel horse assembled from rigid parts, with a procedural gait.
## The node faces -Z (Godot's forward) and its origin sits on the ground.

const VoxelModel := preload("res://scripts/voxel_model.gd")
const HorseModel := preload("res://scripts/horse_model.gd")

const VOXEL := HorseModel.VOXEL

enum Leg { HIND_LEFT, HIND_RIGHT, FORE_LEFT, FORE_RIGHT }

var model: Node3D          # rotated so the model's +X points along -Z
var body: MeshInstance3D
var neck: MeshInstance3D
var head: MeshInstance3D
var tail: Array[MeshInstance3D] = []
var mane: Array[MeshInstance3D] = []
## One entry per Leg: {hip, knee, hoof: MeshInstance3D, front: bool, side: float}
var legs: Array[Dictionary] = []

var _material: StandardMaterial3D


func _init() -> void:
	_build()


func _part(vm: RefCounted, pivot: Vector3, parent: Node3D, offset_vox: Vector3,
		part_name: String, mesh: ArrayMesh = null) -> MeshInstance3D:
	var mi := MeshInstance3D.new()
	mi.name = part_name
	if mesh == null:
		mesh = vm.build_mesh(VOXEL, pivot)
		mesh.surface_set_material(0, _material)
	mi.mesh = mesh
	mi.position = offset_vox * VOXEL
	parent.add_child(mi)
	return mi


func _build() -> void:
	_material = VoxelModel.make_material()
	model = Node3D.new()
	model.name = "Model"
	model.rotation_degrees.y = 90.0
	add_child(model)

	var bp := HorseModel.BODY_PIVOT
	body = _part(HorseModel.build_torso(), bp, model, bp, "Body")

	# Neck, head, mane.
	var np := HorseModel.NECK_PIVOT
	var hp := HorseModel.HEAD_PIVOT
	neck = _part(HorseModel.build_neck(), np, body, np - bp, "Neck")
	head = _part(HorseModel.build_head(), hp, neck, hp - np, "Head")
	_build_mane(np, hp)

	# Tail: a chain of segments hanging from the croup.
	var tp := HorseModel.TAIL_PIVOT
	var parent: Node3D = body
	for i in HorseModel.TAIL_SEGMENTS:
		var off := (tp - bp) if i == 0 else Vector3(0.0, -HorseModel.TAIL_SEG_LEN, 0.0)
		var seg := _part(HorseModel.build_tail_segment(i), Vector3.ZERO, parent, off, "Tail%d" % i)
		tail.append(seg)
		parent = seg

	_build_legs()


func _build_mane(np: Vector3, hp: Vector3) -> void:
	var neck_vec := Vector2(hp.x - np.x, hp.y - np.y)
	var axis := neck_vec.normalized()
	var up_back := Vector2(-axis.y, axis.x) * -1.0   # away from the throat, towards the withers side
	if up_back.y < 0.0:
		up_back = -up_back
	var lengths := [4.2, 4.6, 4.6, 4.2, 3.8, 3.4]
	var meshes: Dictionary = {}
	for i in HorseModel.MANE_TUFTS:
		var t := 0.93 - float(i) * 0.15                  # 0 = base of neck, 1 = poll
		var radius := 1.3 if i < 4 else 1.15
		var crest := Vector2(np.x, np.y) + neck_vec * t + up_back * (lerpf(4.6, 2.7, t) - 0.6)
		var key: float = lengths[i]
		if not meshes.has(key):
			var m := HorseModel.build_mane_tuft(key, radius)
			var mesh := m.build_mesh(VOXEL, Vector3.ZERO)
			mesh.surface_set_material(0, _material)
			meshes[key] = mesh
		var mi := _part(null, Vector3.ZERO, neck, Vector3(crest.x - np.x, crest.y - np.y, 0.0),
				"Mane%d" % i, meshes[key])
		# Rest direction: up and a little back.
		mi.rotation.z = deg_to_rad(38.0)
		mane.append(mi)


func _build_legs() -> void:
	var bp := HorseModel.BODY_PIVOT
	var shared: Dictionary = {}
	for front in [false, true]:
		var upper := HorseModel.build_upper_leg(front).build_mesh(VOXEL, Vector3.ZERO)
		var lower := HorseModel.build_lower_leg(front).build_mesh(VOXEL, Vector3.ZERO)
		upper.surface_set_material(0, _material)
		lower.surface_set_material(0, _material)
		shared[front] = [upper, lower]
	var hoof_mesh := HorseModel.build_hoof().build_mesh(VOXEL, Vector3.ZERO)
	hoof_mesh.surface_set_material(0, _material)

	legs.resize(4)
	for leg in [Leg.HIND_LEFT, Leg.HIND_RIGHT, Leg.FORE_LEFT, Leg.FORE_RIGHT]:
		var front := leg >= Leg.FORE_LEFT
		var side := -1.0 if (leg == Leg.HIND_LEFT or leg == Leg.FORE_LEFT) else 1.0
		var pivot: Vector3 = HorseModel.FORE_PIVOT if front else HorseModel.HIND_PIVOT
		pivot.z *= side
		var upper_len := HorseModel.FORE_UPPER if front else HorseModel.HIND_UPPER
		var lower_len := HorseModel.FORE_LOWER if front else HorseModel.HIND_LOWER
		var tag := ("Fore" if front else "Hind") + ("L" if side < 0.0 else "R")
		var hip := _part(null, Vector3.ZERO, body, pivot - bp, tag + "Hip", shared[front][0])
		var knee := _part(null, Vector3.ZERO, hip, Vector3(0.0, -upper_len, 0.0), tag + "Knee", shared[front][1])
		var hoof := _part(null, Vector3.ZERO, knee, Vector3(0.0, -lower_len, 0.0), tag + "Hoof", hoof_mesh)
		legs[leg] = {"hip": hip, "knee": knee, "hoof": hoof, "front": front, "side": side}

